// The SSH node does NOT throw when the remote command fails. It returns
// node-ssh's result verbatim -- { stdout, stderr, code, signal } -- so a
// failed dry run arrives as a perfectly successful-looking item carrying a
// non-zero `code`. Note the field is `code`, not `exitCode`. Without this
// check a broken script reads as "no worlds found".
const r = $input.first().json;
if (r.code !== 0) {
  throw new Error(`dry run exited ${r.code}: ${(r.stderr || r.stdout || '').trim()}`);
}

const out = r.stdout || '';

// The script's own early exit when there is nothing on disk. It returns 0 and
// never prints the dry-run marker, so it has to be recognised before the
// marker assertion below or a legitimately empty server looks like a failure.
if (/No world folders found/.test(out)) {
  return [{ json: { dryRun: true, count: 0, note: 'no world folders on disk' } }];
}

// Refuse to report on truncated output. The marker is the last line the script
// prints, so its presence means we saw the whole listing rather than a run
// that died partway with a zero exit.
if (!/^--dry-run: nothing was changed\.$/m.test(out)) {
  throw new Error('missing the --dry-run marker; not trusting this output:\n' + out);
}

const dataDir = (out.match(/^Data dir:\s+(.*)$/m) || [])[1] || null;
const mainWorld = (out.match(/^Main world:\s+(.*)$/m) || [])[1] || null;

// The listing is the indented block under the header, ended by a blank line.
// The header says "delete" or "move aside" depending on --backup; match both
// so adding that flag later does not silently yield zero worlds.
const worlds = [];
let inList = false;
for (const line of out.split('\n')) {
  if (/^Worlds to (delete|move aside):$/.test(line)) { inList = true; continue; }
  if (!inList) continue;
  const m = line.match(/^ {2}(\S+)\s+(\S*)\s*$/);
  if (!m) break;
  worlds.push({ json: { dryRun: true, dataDir, mainWorld, world: m[1], size: m[2] || null } });
}

if (worlds.length === 0) {
  throw new Error('parsed the header but found no world rows:\n' + out);
}

return worlds;
